import type { MetadataRoute } from "next";

// Lets the dashboard be installed as an app (Chrome/Edge "Install"), with the
// AI Gateway icon. Icons are generated by scripts/generate-icons.mjs.
export default function manifest(): MetadataRoute.Manifest {
  return {
    name: "AI Gateway",
    short_name: "AI Gateway",
    description:
      "Chat with your models and investigate inference with AI Gateway.",
    start_url: "/",
    display: "standalone",
    background_color: "#1f2226",
    theme_color: "#1f2226",
    icons: [
      { src: "/icons/icon-192.png", sizes: "192x192", type: "image/png" },
      { src: "/icons/icon-512.png", sizes: "512x512", type: "image/png" },
    ],
  };
}
